from agent import *from models.products import *import simplejsonXCAT = ["View the Milex Range", "Request Spares", "How to Guide", "Recipes"]def run(context: dict[str, str], session: Session):    session.queue(Request("https://milex.co.za/", max_age=0), process_frontpage, dict())def process_frontpage(data: Response, context: dict[str, str], session: Session):    cats = data.xpath('//ul[@id="siteNav"]/li[contains(@class, "dropdown")]')    for cat in cats:        name = cat.xpath('a/text()').string()        cats1 = cat.xpath('ul/li')        for cat1 in cats1:            name1 = cat1.xpath('a/text()').string()            if name1 not in XCAT:                cats2 = cat1.xpath('ul/li/a')                if not cats2:                    url = cat1.xpath('a/@href').string()                    session.queue(Request(url, max_age=0), process_prodlist, dict(cat=name+'|'+name1))                    continue                for cat2 in cats2:                    name2 = cat2.xpath('text()').string()                    url = cat2.xpath('@href').string()                    session.queue(Request(url, max_age=0), process_prodlist, dict(cat=name+'|'+name1+'|'+name2))def process_prodlist(data: Response, context: dict[str, str], session: Session):    prods = data.xpath('//div[contains(@class, "products")]//div[@class="details"]')    for prod in prods:        name = prod.xpath('a[contains(@class, "title")]/text()').string()        url = prod.xpath('a[contains(@class, "title")]/@href').string()        revs_cnt = prod.xpath('.//div[@class="jdgm-prev-badge"]/@data-number-of-reviews').string()        if revs_cnt and int(revs_cnt) > 0:            url = 'https://milex.co.za/products/' + url.split('/')[-1]            session.queue(Request(url, max_age=0), process_product, dict(context, name=name, url=url))    # No next pagedef process_product(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name']    product.url = context['url']    product.manufacturer = "Milex"    product.category = context["cat"].replace('View our range', '').strip('| ')    product.ssid = data.xpath('//div[contains(@class, "product")]/div[contains(@class, "jdgm")]/@data-id').string()    mpn = data.xpath('//span[@class="variant-sku"]/text()').string()    if mpn:        product.add_property(type='id.manufacturer', value=mpn)    prod_data = data.xpath("""//script[contains(., '"@type": "Product"')]//text()""").string()    if prod_data:        prod_data = simplejson.loads(prod_data)        ean = prod_data.get('mpn')        if ean:            product.add_property(type='id.ean', value=ean)    revs_url = "https://judge.me/reviews/reviews_for_widget?url=milex-south-africa.myshopify.com&shop_domain=milex-south-africa.myshopify.com&platform=shopify&page=1&per_page=10&product_id=" + product.ssid    session.do(Request(revs_url, max_age=0), process_reviews, dict(product=product))def process_reviews(data: Response, context: dict[str, str], session: Session):    product = context["product"]    json = simplejson.loads(data.content)    html = data.parse_fragment(json["html"])    revs = html.xpath("//div[@class='jdgm-rev jdgm-divider-top']")    for rev in revs:        review = Review()        review.type = 'user'        review.url = product.url        review.ssid = rev.xpath(".//@data-review-id").string()        date = rev.xpath(".//span[@class='jdgm-rev__timestamp jdgm-spinner']/@data-content").string()        if date:            review.date = date.split(" ")[0]        author = rev.xpath(".//span[@class='jdgm-rev__author']/text()[normalize-space()]").string()        if author and author != 'null':            review.authors.append(Person(name=author, ssid=author))        grade_overall = rev.xpath(".//span/@data-score").string()        if grade_overall:            review.grades.append(Grade(type='overall', value=float(grade_overall), best=5.0))        is_verified = rev.xpath('@data-verified-buyer').string()        if is_verified == 'true':            review.add_property(type='is_verified_buyer', value=True)        hlp_yes = rev.xpath('@data-thumb-up-count').string()        if hlp_yes:            review.add_property(type='helpful_votes', value=int(hlp_yes))        hlp_no = rev.xpath('@data-thumb-down-count').string()        if hlp_no:            review.add_property(type='not_helpful_votes', value=int(hlp_no))        title = rev.xpath(".//b[@class='jdgm-rev__title']//text()[normalize-space()]").string(multiple=True)        if title:            title = title.strip('*+=-_\n ')        excerpt = rev.xpath(".//div[@class='jdgm-rev__body']//text()[normalize-space()]").string(multiple=True)        if excerpt:            review.title = title if title and len(title) > 1 else None        elif title:            excerpt = title        if excerpt:            excerpt = excerpt.strip('*+=-_\n ')            if excerpt:                review.properties.append(ReviewProperty(type='excerpt', value=excerpt))                product.reviews.append(review)    next_url = html.xpath('//a[contains(@class, "load-more")]').string()    if next_url:        next_page = context.get("page", 1) + 1        revs_url = 'https://judge.me/reviews/reviews_for_widget?url=milex-south-africa.myshopify.com&shop_domain=milex-south-africa.myshopify.com&platform=shopify&page={}&per_page=10&product_id={}'.format(next_page, product.ssid)        session.do(Request(revs_url, max_age=0), process_reviews, dict(product=product, page=next_page))    elif product.reviews:        session.emit(product)